class Unit:
    _STATES = {"missing", "active", "paused"}

    def __init__(self, name, state="missing"):
        if not isinstance(name, str) or not name:
            raise ValueError("name must be a non-empty string")
        if state not in self._STATES:
            raise ValueError("invalid state")
        self.name = name
        self.state = state


class UnitManager:
    def __init__(self):
        self._events = []

    @property
    def events(self):
        return tuple(self._events)

    @staticmethod
    def _check(unit):
        if not isinstance(unit, Unit):
            raise TypeError("unit must be a Unit")

    def activate(self, unit):
        self._check(unit)
        if unit.state == "missing":
            self._events.append(("create", unit.name))
            unit.state = "paused"
        elif unit.state != "active":
            self._events.append(("start", unit.name))
            unit.state = "active"
        return unit

    def suspend(self, unit):
        self._check(unit)
        if unit.state == "active":
            self._events.append(("stop", unit.name))
            unit.state = "paused"
        return unit

    def remove(self, unit):
        self._check(unit)
        if unit.state != "missing":
            self._events.append(("remove", unit.name))
            unit.state = "missing"
        return unit

